"""Generate the separately classified measured-window host-clock adapter."""
from pathlib import Path
import argparse,hashlib,importlib.util,json
R=Path(__file__).resolve().parents[1];sha=lambda b:hashlib.sha256(b).hexdigest()
PATCHES=[("const sceneEvents=phasedScheduler?stageEvents('scene-camera-copy-events.jsonl'):[];\n", "const measuredPerspectiveWindows=[];\nconst sceneEvents=phasedScheduler?stageEvents('scene-camera-copy-events.jsonl'):[];\n"), ("  const map=boundary.event==='world-perspective-right-written'?afterDrawWorker:beforeDrawWorker;\n", "  if(boundary.event==='world-perspective-right-written'){\n   const after=sceneEvents.find(x=>x.stage===e.stage&&x.event==='scene-camera-copy-after');\n   const reads=read(resolve(nativeHome,'worker-camera-source-read-events.jsonl'),'utf8').trim().split('\\n').map(x=>JSON.parse(x));\n   const sourceRead=reads.find(x=>x.stage===e.stage);\n   assert(e.hostClockSharedAtDebugEventReceipt&&after.hostClockSharedAtDebugEventReceipt&&sourceRead.hostClockSharedAtDebugEventReceipt);\n   assert.equal(e.worldCameraHexAtWorkerEvent,sourceRead.worldCameraHex);\n   assert.equal(sourceRead.worldCameraHex,after.copiedCameraHex);\n   const frameBoundaries=cameraBoundaryEvents.filter(x=>x.event==='world-perspective-right-written'&&x.precedingPlayerCallbacks===callback);\n   const ordinal=frameBoundaries.findIndex(x=>x.debugEventSequence===boundary.debugEventSequence)+1;\n   assert(ordinal>0&&ordinal<frameBoundaries.length);\n   const following=frameBoundaries[ordinal];\n   assert(boundary.hostMonotonicNs<e.hostMonotonicNs&&e.hostMonotonicNs<=sourceRead.hostMonotonicNs&&sourceRead.hostMonotonicNs<=after.hostMonotonicNs&&after.hostMonotonicNs<following.hostMonotonicNs);\n   assert.equal(c.observed_perspective_window(callback,ordinal,baseNow+BigInt(e.hostMonotonicNs)-playerOrigin),1);\n   measuredPerspectiveWindows.push({stage:e.stage,callback,ordinal,readyNs:e.hostMonotonicNs,previousBoundaryNs:boundary.hostMonotonicNs,followingBoundaryNs:following.hostMonotonicNs,sourceReadMainPc:sourceRead.mainThreadRegisters.eip,exactOriginalInstructionScheduleRecovered:false});\n   continue;\n  }\n  const map=boundary.event==='world-perspective-right-written'?afterDrawWorker:beforeDrawWorker;\n"), ("write(resolve(out,'full-camera-report.json'),JSON.stringify({readOnlyExpandedCameraObservation:true,firstCallback:2,callbacksCompared:rows.length/32-1,nativeWordIndices:fullCameraIndices,comparedFieldsPerCallback:71,opaqueNativeWordIndicesNotAccepted:[22,23],nativeTrailingWordsNotCaptured:[73,74],counts:fullCameraCounts,first:fullCameraFirst,allExpandedCapturedWordsEqual:Object.keys(fullCameraCounts).length===0,portableSha256:sha(fullBytes),hostClockOverridesAdded:false,originalStateValuesProvidedToEngine:false,completeGame:false},null,2)+'\\n',{flag:'wx'});\nreport.readOnlyExpandedCameraObservation=true;\n", "write(resolve(out,'full-camera-report.json'),JSON.stringify({readOnlyExpandedCameraObservation:true,firstCallback:2,callbacksCompared:rows.length/32-1,nativeWordIndices:fullCameraIndices,comparedFieldsPerCallback:71,opaqueNativeWordIndicesNotAccepted:[22,23],nativeTrailingWordsNotCaptured:[73,74],counts:fullCameraCounts,first:fullCameraFirst,allExpandedCapturedWordsEqual:Object.keys(fullCameraCounts).length===0,portableSha256:sha(fullBytes),hostClockOverridesAdded:true,originalStateValuesProvidedToEngine:false,completeGame:false},null,2)+'\\n',{flag:'wx'});\nreport.readOnlyExpandedCameraObservation=true;report.measuredPerspectiveWindows=measuredPerspectiveWindows;report.addedMeasuredHostClockBoundary=true;report.exactOriginalInstructionScheduleRecovered=false;report.ordinaryIndependentThreadTimingAcceptance=false;\nassert.equal(c.observed_perspective_window_state(0),1);assert.equal(c.observed_perspective_window_state(1),0);\n")]
def driver_source():
 spec=importlib.util.spec_from_file_location('camera',R/'tools/th14-prepare-full-camera-drivers-nov04.py');g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
 text=g.driver_source().decode().replace('\r\n','\n')
 for old,new in PATCHES:
  assert text.count(old)==1; text=text.replace(old,new)
 return text.replace('\n','\r\n').encode()

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true',required=True);p.parse_args()
 path=R/'tools/th14-compare-native-observed-perspective-window-nov04.mjs';data=driver_source();assert data==path.read_bytes()
 print(json.dumps(dict(driverSha256=sha(data),hostClockOverridesAdded=True,originalValuesInjected=False,exactOriginalInstructionScheduleRecovered=False,completeGame=False)))
if __name__=='__main__':main()
